import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, step, uniform, float, sub, min, mul, add, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, Vector3 } = ctx.THREE;

  // ---------- Geometry ----------
  const width = 2.6;
  const height = 0.68;
  const radius = 0.08;
  const depth = 0.03;

  const shape = new Shape();
  shape.moveTo(-width / 2 + radius, -height / 2);
  shape.lineTo(width / 2 - radius, -height / 2);
  shape.absarc(width / 2 - radius, -height / 2 + radius, radius, -Math.PI / 2, 0, false);
  shape.lineTo(width / 2, height / 2 - radius);
  shape.absarc(width / 2 - radius, height / 2 - radius, radius, 0, Math.PI / 2, false);
  shape.lineTo(-width / 2 + radius, height / 2);
  shape.absarc(-width / 2 + radius, height / 2 - radius, radius, Math.PI / 2, Math.PI, false);
  shape.lineTo(-width / 2, -height / 2 + radius);
  shape.absarc(-width / 2 + radius, -height / 2 + radius, radius, Math.PI, 3 * Math.PI / 2, false);

  const extrudeSettings = {
    depth,
    bevelEnabled: true,
    bevelThickness: depth,
    bevelSize: radius,
    bevelSegments: 2,
    steps: 1,
  };
  const geometry = new ExtrudeGeometry(shape, extrudeSettings);
  geometry.translate(0, 0, -depth / 2); // center on Z=0

  // ---------- Material ----------
  const emissiveIntensity = uniform(1.6);
  const edgeWidthUV = float(0.015 / width); // approx

  const uvNode = uv();
  const y = uvNode.y;

  const col0 = color('#ff4450');
  const col1 = color('#ff2a38');
  const col2 = color('#c1121f');
  const accentCol = color('#ff2a38');

  const t1 = smoothstep(float(0.0), float(0.55), y);
  const grad1 = mix(col0, col1, t1);
  const t2 = smoothstep(float(0.55), float(1.0), y);
  const finalColor = mix(grad1, col2, t2);

  const minX = min(uvNode.x, sub(float(1.0), uvNode.x));
  const minY = min(uvNode.y, sub(float(1.0), uvNode.y));
  const minDist = min(minX, minY);
  const edgeMask = step(edgeWidthUV, minDist);
  const emissiveColor = mul(accentCol, mul(edgeMask, emissiveIntensity));

  const material = new MeshStandardNodeMaterial();
  material.colorNode = finalColor;
  material.emissiveNode = emissiveColor;
  material.roughness = 0.5;
  material.metalness = 0.35;
  material.clearcoat = 0.22;
  material.clearcoatRoughness = 0.25;

  // ---------- Mesh ----------
  const buttonMesh = new Mesh(geometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const group = new Group();
  group.add(buttonMesh);

  const labelItem = items.find(i => i.role === 'cta-label') || { text: 'BEGIN COMMISSION' };
  const captionItem = items.find(i => i.role === 'caption') || { text: 'NO DEPOSIT REQUIRED' };

  const label = ctx.fontAtlas.createText(labelItem.text, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08 * 20,
  });
  label.position.set(0, 0, depth / 2 + 0.001);
  group.add(label);

  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * 9,
  });
  caption.position.set(0, -height / 2 - 0.25, depth / 2 + 0.001);
  group.add(caption);

  // ---------- Animations ----------
  const timelines = [];

  // entrance weighted‑settle
  group.scale.set(1.04, 1.04, 1.04);
  const entrance = gsap.timeline({ paused: true });
  entrance.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  entrance.play();
  timelines.push(entrance);

  // hover & press handlers
  const hoverEnter = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(buttonMesh.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    tl.to(emissiveIntensity, {
      value: 2.2,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.play();
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(buttonMesh.position, {
      z: 0,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    tl.to(emissiveIntensity, {
      value: 1.6,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.play();
    timelines.push(tl);
  };
  const press = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    tl.play();
    timelines.push(tl);
  };
  const release = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    tl.play();
    timelines.push(tl);
  };

  // ---------- UserData ----------
  group.userData.handlers = {
    hoverEnter,
    hoverLeave,
    press,
    release,
  };
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
    // text objects are disposed by the atlas when removed; we just remove them
    group.traverse(child => {
      if (child.isMesh && child.geometry) child.geometry.dispose();
      if (child.isMesh && child.material) child.material.dispose();
    });
  };

  return group;
}
